                feld.className = 'hr-pl';

                const istZiel = laeuft && platz.id === magazin.tar_id;
                const istAuf = !laeuft && platz.id === magazin.tar_id && platz.present;
                const istQuelle = laeuft && platz.id === magazin.src_id;
